using System.Text.Json;
using Seamless.Management;
using Seamless.Management.Server;

namespace Management.Tests;

[Collection("AuditStorage")]
public sealed class UpdateAuditUpgrade{
    private static string Root()=>Path.Combine(Environment.GetEnvironmentVariable("SEAMLESS_MANAGEMENT_TEST_ROOT")??throw new InvalidOperationException("Missing isolated root."),Guid.NewGuid().ToString("N"));
    private static UserAccount Login(Seamless.Management.Server.ManagementService service)=>service.Authenticate(service.Login(new("admin","TestPassword-123")).Token);
    private static Definition Query(string id,string body,bool writes=false)=>new(id,"Native",DefinitionKind.Query,"Model.Queries","Run",new("1",[new("Query.cs","using System.Linq;using Seamless.Management.Server;namespace Model;public static class Queries{public static int Run(ManagementExecutionContext context){"+body+"}}")],[]),writes);
    private static ExecuteRequest Request(string id)=>new(id,null,ManagementJson.Element(new{}));
    private static Dictionary<string,string> Snapshot(string root)=>Directory.GetFiles(root,"*",SearchOption.AllDirectories).ToDictionary(path=>Path.GetRelativePath(root,path),static path=>{using var stream=File.OpenRead(path);return Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(stream));});
    private static string Legacy(Definition? definition=null){
        var root=Root();using(var store=ManagementStore.InitializeLegacy(root,"admin","TestPassword-123"))using(var service=new Seamless.Management.Server.ManagementService(store)){var user=Login(service);NativeWorkflow.Publish(service,user,definition??NativeWorkflow.Database());NativeWorkflow.Publish(service,user,Query("insert","context.GetDatabase<Db>().Rows.Add(new Tables.Row(new(1),9));return 9;",true));NativeWorkflow.Publish(service,user,Query("sum","return context.GetDatabase<Db>().Rows.Sum(row=>row.Value);"));_=service.Execute(user,Request("insert"),CancellationToken.None).ToArray();service.SaveDraft(user,new((definition??NativeWorkflow.Database()) with{Source=(definition??NativeWorkflow.Database()).Source with{Revision="personal"}},1,1));service.ChangeUser(user,new("disabled","DisabledPassword-123",[new("Native",ManagementPermission.View)],true));}
        ManagementStoreUpgrade.Upgrade(root,root+"-system-backup");return root;
    }
    [Fact]public async Task ExplicitEnablePreservesDataSourceDraftsAndPermissionsAndPublishesAudit(){
        var root=Legacy();DefinitionVersion original;Draft draft;UserAccount disabled;using(var before=new ManagementStore(root)){original=before.Read<DefinitionVersion>("active","db")!;draft=before.Read<Draft>("draft","ADMIN:db")!;disabled=before.Read<UserAccount>("user","DISABLED")!;}
        var backup=root+"-enable-backup";var result=Seamless.Management.Server.UpdateAuditUpgrade.Enable(root,"Native",backup);Assert.Equal(OperationState.Succeeded,result.State);Assert.Equal(2,result.PublishedVersion);Assert.Equal(result,Seamless.Management.Server.UpdateAuditUpgrade.GetOperation(root,result.Id));
        using(var restored=new ManagementStore(backup))using(var service=new Seamless.Management.Server.ManagementService(restored)){var actor=Login(service);Assert.Equal(1,service.GetDefinition(actor,"db").Version);Assert.Equal(9,Assert.Single(service.Execute(actor,Request("sum"),CancellationToken.None)).Value.GetInt32());Assert.Empty(restored.List<AuditOrigin>("auditOrigin").Items);}
        using var store=new ManagementStore(root);using var current=new Seamless.Management.Server.ManagementService(store);var user=Login(current);var active=current.GetDefinition(user,"db");Assert.Equal(original.Definition.Hash(),active.Definition.Hash());Assert.Equal(original.Definition.Source.Hash(),active.Definition.Source.Hash());Assert.NotEqual(original.StoragePath,active.StoragePath);Assert.NotEqual(original.ArtifactHash,active.ArtifactHash);var savedDraft=store.Read<Draft>("draft","ADMIN:db")!;Assert.Equal(draft.Definition.Hash(),savedDraft.Definition.Hash());Assert.Equal(draft.Revision,savedDraft.Revision);Assert.Equal(draft.BaseVersion,savedDraft.BaseVersion);var savedUser=store.Read<UserAccount>("user","DISABLED")!;Assert.Equal(disabled.PasswordHash,savedUser.PasswordHash);Assert.Equal(disabled.Disabled,savedUser.Disabled);Assert.Equal(disabled.Grants,savedUser.Grants);Assert.Equal(9,Assert.Single(current.Execute(user,Request("sum"),CancellationToken.None)).Value.GetInt32());NativeWorkflow.Publish(current,user,Query("second","context.GetDatabase<Db>().Rows.Add(new Tables.Row(new(2),5));return 5;",true));_=current.Execute(user,Request("second"),CancellationToken.None).ToArray();using var timeout=new CancellationTokenSource(TimeSpan.FromSeconds(30));while(store.AuditEvents(new(Action:AuditAction.DataChange)).Items.Length==0){await Task.Delay(30,timeout.Token);}Assert.Single(store.AuditEvents(new(Action:AuditAction.DataChange)).Items);
    }
    [Fact]public void LiveRootAndFailedBackupDoNotModifyTheSource(){var root=Legacy();using(var live=new ManagementStore(root)){Assert.Throws<IOException>(()=>Seamless.Management.Server.UpdateAuditUpgrade.Enable(root,"Native",root+"-backup"));Assert.Equal(1,live.Read<DefinitionVersion>("active","db")!.Version);}var before=Snapshot(root);var invalid=root+"-invalid";File.WriteAllText(invalid,"occupied");Assert.Throws<IOException>(()=>Seamless.Management.Server.UpdateAuditUpgrade.Enable(root,"Native",invalid));Assert.Equal(before.OrderBy(static pair=>pair.Key),Snapshot(root).OrderBy(static pair=>pair.Key));}
    [Fact]public void PreviousConversionExpressionsAreNotAppliedAgain(){var definition=NativeWorkflow.Database() with{Migration=new(1,[new("Rows","Rows",[new("Id","Id"),new("Value","Value","row.Value+100")],[])],[])};var root=Legacy(definition);var result=Seamless.Management.Server.UpdateAuditUpgrade.Enable(root,"Native",root+"-backup");Assert.Equal(OperationState.Succeeded,result.State);using var store=new ManagementStore(root);using var service=new Seamless.Management.Server.ManagementService(store);Assert.Equal(9,Assert.Single(service.Execute(Login(service),Request("sum"),CancellationToken.None)).Value.GetInt32());Assert.Equal(definition.Hash(),service.GetDefinition(Login(service),"db").Definition.Hash());}
    [Fact]public void RepeatedOperationAndAlreadyEnabledDoNotCreateAnotherGeneration(){
        var root=Legacy();var id=Guid.NewGuid();var first=Seamless.Management.Server.UpdateAuditUpgrade.Enable(root,"Native",root+"-first",id);Assert.Equal(OperationState.Succeeded,first.State);Assert.Equal(first,Seamless.Management.Server.UpdateAuditUpgrade.Enable(root,"Native",root+"-retry",id));Assert.Equal("Conflict",Assert.Throws<ManagementException>(()=>Seamless.Management.Server.UpdateAuditUpgrade.Enable(root,"Other",root+"-conflict",id)).Code);var already=Seamless.Management.Server.UpdateAuditUpgrade.Enable(root,"Native",root+"-already");Assert.Equal(OperationState.Succeeded,already.State);Assert.Equal(2,already.PublishedVersion);using var store=new ManagementStore(root);Assert.Equal(2,store.Read<DefinitionVersion>("active","db")!.Version);Assert.Equal(2,store.Read<DefinitionVersion>("active","sum")!.Version);Assert.Single(store.List<AuditOrigin>("auditOrigin").Items);
    }
    [Theory][InlineData("Prepared",false,OperationState.Failed,1)][InlineData("Copy:BeforeConstraints",true,OperationState.Cancelled,1)][InlineData("Committed",false,OperationState.Succeeded,2)]public void FailureCancellationAndLostResponseKeepTheCorrectPublishedVersion(string phase,bool cancel,OperationState expected,long version){
        var root=Legacy();using var cancellation=new CancellationTokenSource();Seamless.Management.Server.UpdateAuditUpgrade.Checkpoint=(current,_)=>{if(current!=phase){return;}if(cancel){cancellation.Cancel();}else{throw new IOException("injected "+phase);}};OperationInfo result;try{result=Seamless.Management.Server.UpdateAuditUpgrade.Enable(root,"Native",root+"-backup",cancellation:cancellation.Token);}finally{Seamless.Management.Server.UpdateAuditUpgrade.Checkpoint=null;}
        Assert.Equal(expected,result.State);Assert.Equal(result,Seamless.Management.Server.UpdateAuditUpgrade.GetOperation(root,result.Id));using var store=new ManagementStore(root);using var service=new Seamless.Management.Server.ManagementService(store);var user=Login(service);Assert.Equal(version,service.GetDefinition(user,"db").Version);Assert.Equal(version,service.GetDefinition(user,"sum").Version);Assert.Equal(9,Assert.Single(service.Execute(user,Request("sum"),CancellationToken.None)).Value.GetInt32());Assert.Equal(version-1,store.List<AuditOrigin>("auditOrigin").Items.LongLength);Assert.Equal(version==2,service.History(user).Items.Any(item=>item.Action=="UpdateAuditEnabled"));
    }
    [Fact]public void CancellationAfterBackupLeavesTheSourceUnchanged(){var root=Legacy();var before=Snapshot(root);using var cancellation=new CancellationTokenSource();Seamless.Management.Server.UpdateAuditUpgrade.Checkpoint=(phase,_)=>{if(phase=="BackupCompleted"){cancellation.Cancel();}};try{Assert.Throws<OperationCanceledException>(()=>Seamless.Management.Server.UpdateAuditUpgrade.Enable(root,"Native",root+"-backup",cancellation:cancellation.Token));}finally{Seamless.Management.Server.UpdateAuditUpgrade.Checkpoint=null;}Assert.Equal(before.OrderBy(static item=>item.Key),Snapshot(root).OrderBy(static item=>item.Key));}
    [Fact]public void SelfReferenceCompositeThreeCycleAndAnotherDatabaseSurviveTheCopy(){
        var root=Root();var source=NativeRelationScenarios.Composite.Replace("public Schema Nested=>","[ForeignKey(\"SS\",\"Self\",new[]{\"Tenant\",\"Other\"},new[]{\"Tenant\",\"Id\"})]public Table<Keys.Row,Tables.Row> Self=>this.Table<Keys.Row,Tables.Row>(row=>new(row.Tenant,row.Id));public Schema Nested=>",StringComparison.Ordinal);var database=new Definition("db","Native",DefinitionKind.Database,"Shapes.Db","",new("1",[new("shape.cs",source)],[]));
        Definition query(string id,string body,bool writes=false)=>new(id,"Native",DefinitionKind.Query,"Shapes.Query","Run",new("1",[new("query.cs","using Seamless.Management.Server;namespace Shapes;public static class Query{public static int Run(ManagementExecutionContext context){var db=context.GetDatabase<Db>();"+body+"}}")],[]),writes);
        var count=query("count","return db.As.Count+db.Bs.Count+db.Nested.Cs.Count+db.Self.Count;");var seed=query("seed","db.As.Add(new Tables.Row(new(3,1),2));db.Bs.Add(new Tables.Row(new(3,2),3));db.Nested.Cs.Add(new Tables.Row(new(3,3),1));db.Self.Add(new Tables.Row(new(3,10),11));db.Self.Add(new Tables.Row(new(3,11),10));db.Self.Add(new Tables.Row(new(3,12),12));return 6;",true);DefinitionVersion other;
        using(var store=ManagementStore.InitializeLegacy(root,"admin","TestPassword-123"))using(var service=new Seamless.Management.Server.ManagementService(store)){var user=Login(service);NativeWorkflow.Publish(service,user,database);NativeWorkflow.Publish(service,user,seed);NativeWorkflow.Publish(service,user,count);Assert.Equal(6,Assert.Single(service.Execute(user,Request("seed"),CancellationToken.None)).Value.GetInt32());NativeWorkflow.Publish(service,user,NativeWorkflow.Database() with{Id="other",Database="Other"});NativeWorkflow.Publish(service,user,Query("otherInsert","context.GetDatabase<Db>().Rows.Add(new Tables.Row(new(1),21));return 21;",true) with{Database="Other"});NativeWorkflow.Publish(service,user,Query("otherSum","return context.GetDatabase<Db>().Rows.Sum(row=>row.Value);") with{Database="Other"});_=service.Execute(user,Request("otherInsert"),CancellationToken.None).ToArray();other=service.GetDefinition(user,"other");}
        ManagementStoreUpgrade.Upgrade(root,root+"-system-backup");var result=Seamless.Management.Server.UpdateAuditUpgrade.Enable(root,"Native",root+"-backup");Assert.Equal(OperationState.Succeeded,result.State);using var reopened=new ManagementStore(root);using var current=new Seamless.Management.Server.ManagementService(reopened);var actor=Login(current);Assert.Equal(6,Assert.Single(current.Execute(actor,Request("count"),CancellationToken.None)).Value.GetInt32());var unchanged=current.GetDefinition(actor,"other");Assert.Equal(other.Version,unchanged.Version);Assert.Equal(other.StoragePath,unchanged.StoragePath);Assert.Equal(other.ArtifactHash,unchanged.ArtifactHash);Assert.Equal(other.Definition.Hash(),unchanged.Definition.Hash());Assert.Equal(21,Assert.Single(current.Execute(actor,Request("otherSum"),CancellationToken.None)).Value.GetInt32());NativeWorkflow.Publish(current,actor,query("orphan","db.Self.Add(new Tables.Row(new(3,99),100));return 1;",true));Assert.ThrowsAny<Exception>(()=>current.Execute(actor,Request("orphan"),CancellationToken.None).ToArray());Assert.Equal(6,Assert.Single(current.Execute(actor,Request("count"),CancellationToken.None)).Value.GetInt32());
    }
    private static async Task<(int ExitCode,System.Text.Json.JsonElement[] Output)> Child(params string[] arguments){
        var probe=arguments[0]=="--update-audit-upgrade-probe";
        var start=new System.Diagnostics.ProcessStartInfo("dotnet"){
            UseShellExecute=false,CreateNoWindow=true,WindowStyle=System.Diagnostics.ProcessWindowStyle.Hidden,
            RedirectStandardOutput=true,RedirectStandardError=true,RedirectStandardInput=probe
        };
        start.ArgumentList.Add(typeof(CrashProbe).Assembly.Location);
        foreach(var argument in arguments){start.ArgumentList.Add(argument);}
        using var process=System.Diagnostics.Process.Start(start)!;
        using var timeout=new CancellationTokenSource(TimeSpan.FromSeconds(90));
        try{
            var error=process.StandardError.ReadToEndAsync(timeout.Token);
            string? ready=null;
            if(probe){
                ready=await process.StandardOutput.ReadLineAsync(timeout.Token);
                var receipt=JsonSerializer.Deserialize<JsonElement>(Assert.IsType<string>(ready));
                Assert.Equal(process.Id,receipt.GetProperty("Pid").GetInt32());
                Assert.True(LocalProcessIdentity.Matches(process.Id,receipt.GetProperty("Created").GetDateTime(),receipt.GetProperty("ProcessIdentity").GetString()));
                await process.StandardInput.WriteLineAsync("exit").WaitAsync(timeout.Token);
                await process.StandardInput.FlushAsync(timeout.Token);
            }
            var output=process.StandardOutput.ReadToEndAsync(timeout.Token);
            Assert.True(process.WaitForExit(90000));Assert.Empty(await error);
            var rows=((ready??"")+"\n"+await output).Split('\n',StringSplitOptions.RemoveEmptyEntries).Select(static line=>JsonSerializer.Deserialize<JsonElement>(line)).ToArray();
            return(process.ExitCode,rows);
        }finally{
            if(!process.HasExited){process.Kill(entireProcessTree:true);Assert.True(process.WaitForExit(90000));}
        }
    }
    [Fact]public async Task CliReportsTheOperationIdAndCanQueryItsDurableResult(){var root=Legacy();var id=Guid.NewGuid();var enabled=await Child("--management-cli","enable-update-audit","--root",root,"--database","Native","--backup",root+"-backup","--operation-id",id.ToString());Assert.Equal(0,enabled.ExitCode);Assert.Equal(2,enabled.Output.Length);Assert.Equal(id,enabled.Output[0].GetProperty("operationId").GetGuid());Assert.Equal("Requested",enabled.Output[0].GetProperty("phase").GetString());var result=enabled.Output[1].Deserialize<OperationInfo>(ManagementJson.Options)!;Assert.Equal(OperationState.Succeeded,result.State);var queried=await Child("--management-cli","get-operation","--root",root,"--operation-id",id.ToString());Assert.Equal(0,queried.ExitCode);Assert.Equal(result,Assert.Single(queried.Output).Deserialize<OperationInfo>(ManagementJson.Options));}
    [Theory][InlineData("Prepared",false)][InlineData("Committed",true)]public async Task AbruptTerminationKeepsPublicationAndOperationResultTogether(string phase,bool committed){
        var root=Legacy();var id=Guid.NewGuid();var stopped=await Child("--update-audit-upgrade-probe",root,phase,id.ToString());Assert.Equal(137,stopped.ExitCode);var receipt=Assert.Single(stopped.Output);Assert.Equal(phase,receipt.GetProperty("Phase").GetString());if(OperatingSystem.IsWindows()||OperatingSystem.IsLinux()){using var current=System.Diagnostics.Process.GetCurrentProcess();Assert.Equal(current.ProcessorAffinity.ToInt64(),receipt.GetProperty("Affinity").GetInt64());}var result=Seamless.Management.Server.UpdateAuditUpgrade.GetOperation(root,id);var state=OperationState.OutcomeUnknown;var version=1L;if(committed){state=OperationState.Succeeded;version=2;}Assert.Equal(state,result.State);using var store=new ManagementStore(root);using var service=new Seamless.Management.Server.ManagementService(store);var user=Login(service);Assert.Equal(version,service.GetDefinition(user,"db").Version);Assert.Equal(version,service.GetDefinition(user,"sum").Version);Assert.Equal(9,Assert.Single(service.Execute(user,Request("sum"),CancellationToken.None)).Value.GetInt32());Assert.Equal(version-1,store.List<AuditOrigin>("auditOrigin").Items.LongLength);
    }
    internal static int RunStopProbe(string root,string phase,Guid id){
        Seamless.Management.Server.UpdateAuditUpgrade.Checkpoint=(current,operation)=>{
            if(current!=phase){return;}
            using var process=System.Diagnostics.Process.GetCurrentProcess();long? affinity=null;
            if(OperatingSystem.IsWindows()||OperatingSystem.IsLinux()){affinity=process.ProcessorAffinity.ToInt64();}
            var created=process.StartTime.ToUniversalTime();
            var identity=LocalProcessIdentity.Capture(process.Id,created);
            Console.WriteLine(JsonSerializer.Serialize(new{Id=operation,Pid=process.Id,Created=created,ProcessIdentity=identity,Affinity=affinity,Phase=phase}));
            Console.Out.Flush();
            // OS識別を生存中に親が照合した後、同じ確定境界で強制終了する。
            if(Console.ReadLine()!="exit"){Environment.Exit(2);}
            Environment.Exit(137);
        };
        _=Seamless.Management.Server.UpdateAuditUpgrade.Enable(root,"Native",root+"-backup",id);return 3;
    }
}
